private static readonly UInt32 SPI_SETDESKWALLPAPER = 0x14;    private static readonly UInt32 WM_SETTINGCHANGE = 0x1A;      private void timer1_Tick(object sender, EventArgs e) {            Message m = new Message();            m.Msg = (int)WM_SETTINGCHANGE;            m.WParam = (IntPtr)SPI_SETDESKWALLPAPER;            WndProc(ref m);        }        protected override void WndProc(ref Message message) {            if (message.Msg == WM_SETTINGCHANGE) {                if (message.WParam.ToInt32() == SPI_SETDESKWALLPAPER) {                    // Handle that wallpaper has been changed.]                    Console.Beep();                }            }            base.WndProc(ref message);        }